    if (!(cin >> n >> m)) return 0;

    vector<vector<pair<int, long long>>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        long long w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
    }

    // State encoding: state = (u << 1) | used
    vector<long long> dist(2 * n + 2, INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;

    int start = (1 << 1);
    dist[start] = 0;
    pq.push({0, start});

    while (!pq.empty()) {
        auto [d, state] = pq.top();
        pq.pop();
        if (d != dist[state]) continue;

        int u = state >> 1;
        int used = state & 1;

        for (const auto& [v, w] : adj[u]) {
            int ns = (v << 1) | used;
            long long nd = d + w;
            if (nd < dist[ns]) {
                dist[ns] = nd;
                pq.push({nd, ns});
            }
            if (used == 0) {
                int ns1 = (v << 1) | 1;
                long long nd1 = d + (w >> 1);
                if (nd1 < dist[ns1]) {
                    dist[ns1] = nd1;
                    pq.push({nd1, ns1});
                }
            }
        }
